<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/cloud-cost-fixture.php';require __DIR__.'/commerce-fixture.php';require __DIR__.'/support/HttpTestServer.php';
use Hostider\Core\{Id,Config};use Hostider\Core\Database\Migrator;use Hostider\Cloud\Worker;use Hostider\Commerce\Services;
$db=isolatedDomainDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();$seed=cloudFixture($db);$c=new Services($db,$seed['config']);$admin=commerceAdmin($c);$client=commerceUser($c,'panel-client');$outsider=commerceUser($c,'panel-outsider');$env=cloudEnv($seed);$env['HTTP_TEST_ENGINE']='interpreter';$server=new HttpTestServer(dirname(__DIR__),$env,__DIR__.'/commerce-router.php');$second=new HttpTestServer(dirname(__DIR__),$env,__DIR__.'/commerce-router.php');$jars=['client'=>[],'admin'=>[]];$tokens=['client'=>'','admin'=>''];$examples=[];
function panelHttp(string $path,?array $body=null,?string $key=null,bool $csrf=true,?string $method=null): array
{
    global $server,$jars,$tokens;$ctx=str_contains($path,'/admin')?'admin':'client';$options=[];if($jars[$ctx]){$options[CURLOPT_COOKIE]=implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($jars[$ctx]),$jars[$ctx]));}
    if($body!==null){$h=['Content-Type: application/json','Idempotency-Key: '.($key??Id::uuid())];if($csrf){$h[]='X-CSRF-Token: '.$tokens[$ctx];}$options+=[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode((object)$body,JSON_THROW_ON_ERROR),CURLOPT_HTTPHEADER=>$h];}if($method){$options[CURLOPT_CUSTOMREQUEST]=$method;}
    [$status,$raw,$headers]=$server->request($path,$options);foreach($headers as $header){if(preg_match('/^Set-Cookie: ([^=]+)=([^;]*)/i',$header,$m)){$jars[$ctx][$m[1]]=$m[2];}}$json=json_decode($raw,true);if(isset($json['data']['csrf'])){$tokens[$ctx]=$json['data']['csrf'];}return [$status,$json,$raw,$headers];
}
function panelBind(array $f): void
{
    global $db,$c,$client,$admin;$db->execute('INSERT INTO identity_memberships(user_id,customer_id,is_owner) VALUES (?,?,TRUE)',[$client['user'],$f['customer']]);$role=$db->execute("SELECT id FROM identity_roles WHERE name='Müşteri Sahibi'")->fetchColumn();$db->transaction(fn()=>$c->identity->assign($client['user'],$role,$f['customer']));
    $assignment=$db->execute('SELECT id FROM identity_assignments WHERE user_id=? AND customer_id IS NULL',[$admin['user']])->fetchColumn();foreach(['services.view','services.manage','services.reconcile','finance.view','finance.approve'] as $perm){$db->execute('INSERT INTO identity_grants(id,assignment_id,permission,customer_scope,service_scope) VALUES (?,?,?,?,?)',[Id::uuid(),$assignment,$perm,$f['customer'],$f['service']['id']]);}
}
function panelCloud(bool $active=true): array{global $db;$f=cloudFixture($db);panelBind($f);if($active){activateCloud($db,$f);}return $f;}
function panelCost(): array
{
    global $db,$admin;$f=panelCloud();$i=$f['engine']->store->instance($f['instance'],false);$now=\Hostider\CloudCosts\Store::date(gmdate('Y-m-d H:i:s'));
    $policy=['currency'=>'USD','hourly'=>'0.2','quantum_seconds'=>1,'minimum_seconds'=>0,'minimum_minor'=>'0','rounding'=>'HALF_UP','tax_rate'=>'0','addons'=>[],'fees'=>[],'valid_from'=>$now->modify('-2 days')->format('Y-m-d H:i:s'),'valid_until'=>$now->modify('+365 days')->format('Y-m-d H:i:s'),'max_age_seconds'=>86400,'spec_hash'=>$i['fingerprint'],'fx'=>null,'provenance'=>'MOCK'];
    $tariff=(new \Hostider\CloudCosts\Tariffs($db,$f['config']))->publish($i['account_id'],$policy,$admin['reference']);return array_replace($f,compact('i','now','tariff'),['cost_policy'=>$policy,'cost'=>new \Hostider\CloudCosts\Engine($db,$f['config']),'meter'=>new \Hostider\Providers\Mock\CloudMetering($db,$f['config'])]);
}
function panelSelect(array $f): void{$GLOBALS['db']->execute('DELETE FROM rate_limits');same(200,panelHttp('/api/v1/client/identity/switch',['customer'=>$f['customer']])[0]);}
function panelData(array $f,string $kind='STOP',array $data=[]): array{return ['action'=>'cloud-action','customer'=>$f['customer'],'payload'=>(object)['service_id'=>$f['service']['id'],'kind'=>$kind,'data'=>(object)$data]];}
function panelPrepare(array $data,string $ctx='client'): array{return panelHttp('/api/v1/'.$ctx.'/provider-panel/prepare',$data);}
function panelExecute(array $data,string $confirmation,string $ctx='client',?string $key=null): array{$data['confirmation']=(object)['id'=>$confirmation,'accepted'=>true];return panelHttp('/api/v1/'.$ctx.'/provider-panel/execute',$data,$key);}
function panelCommand(array $data,string $ctx='admin'): array{$r=panelPrepare($data,$ctx);if($r[0]!==200){return $r;}return panelExecute($data,$r[1]['data']['id'],$ctx);}
function panelConcurrent(array $data,string $confirmation,bool $sameKey=false): array
{
    global $server,$second,$jars,$tokens,$env;$key=Id::uuid();$children=[];$body=$data;$body['confirmation']=(object)['id'=>$confirmation,'accepted'=>true];$cookie=implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($jars['client']),$jars['client']));
    foreach([$server,$second] as $srv){$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/provider-panel-http-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,$env);if(!is_resource($p)){throw new RuntimeException('HTTP child unavailable');}fwrite($pipes[0],json_encode(['url'=>'http://127.0.0.1:'.$srv->diagnostics()['port'].'/api/v1/client/provider-panel/execute','body'=>$body,'key'=>$sameKey?$key:Id::uuid(),'cookie'=>$cookie,'csrf'=>$tokens['client']],JSON_THROW_ON_ERROR));fclose($pipes[0]);$children[]=[$p,$pipes];}
    $out=[];$bad=false;foreach($children as [$p,$pipes]){$raw=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($p);$bad=$bad||$exit!==0||$err!=='';$out[]=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}same(false,$bad);return $out;
}
